css:
.pl { list-style: none; padding: 0; margin: 0; }
.pl li { margin: 0 0 .6rem; break-inside: avoid; }
.pl--two { columns: 2; column-gap: 2rem; }
.pl--one { max-width: 40rem; }
.pl a { color: var(--os-color-link); text-decoration: underline; text-underline-offset: .2em; }
@media (max-width: 767px) { .pl--two { columns: 1; } }
